/* Splice value tags (CRef::m_tagk; docs/engine/splice-scripting.md section 2), named for this file. The shared TAGK
   enum (sly2/basic.h, sly2/cref.h) defines only TAGK_Nil = -1 so far; these are plain constants so that the views below
   can keep taking `int` tags. 0x12 is the quote special form's head tag, used when the builtins build (quote x). */
enum
{
    TAGK_QUOTE = 0x12,
    TAGK_S32 = 0x15,
    TAGK_F32 = 0x16,
    TAGK_BOOL = 0x17,
    TAGK_SYMID = 0x18,
    TAGK_BIFK = 0x19,          /* a builtin function id */
    TAGK_VECTOR = 0x1A,
    TAGK_MATRIX = 0x1B,
    TAGK_CLQ = 0x1C,           /* quadratic coefficients */
    TAGK_LM = 0x1D,            /* limits (min, max) */
    TAGK_SMP = 0x1E,           /* smoothing parameters */
    TAGK_PAIR = 0x1F,
    TAGK_PROC = 0x20,
    TAGK_BASIC = 0x21,         /* an object */
    TAGK_METHOD = 0x22,
    TAGK_VOID = 0x24,
};

/* 16-byte vector as the builtins pass it (the payload heaps hold quadwords; sly2/basic.h's VECTOR is 12 bytes, its
   VECTOR4 the same layout under another name). VU_VECTOR's constructor keeps its mangled name (RC6VECTOR). */
struct VECTORQ { float x, y, z, w; } __attribute__((aligned(16)));
struct BASIC;
struct PAIRV;
/* A Splice value (tag + one-word payload; the layout of sly2/cref.h's CRef, as a POD so that it can be passed by
   pointer to the C-named constructors without its inline members). */
struct CREFV
{
    int m_tagk;
    union { int n; float g; void *pv; PAIRV *ppair; MATRIX4 *pmat; VECTORQ *pvec; } u;
};
/* A list pair (pool 0): its value at +8 and the next pair at +0x10. */
struct PAIRV { int cref; int n4; CREFV ref; PAIRV *ppairNext; };
